class Solution:
    def maxFixedPoints(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [1] * n
        ans = 1
        for i in range(n):
            ci = i - nums[i]
            for j in range(i):
                if j - nums[j] <= ci and nums[i] >= dp[j]:
                    dp[i] = max(dp[i], dp[j] + 1)
            ans = max(ans, dp[i])
        return ans

