        vector<int> dp(n, 1);
        for (int i = 0; i < n; ++i) {
            int ci = i - nums[i];
            for (int j = 0; j < i; ++j)
                if (j - nums[j] <= ci && nums[i] >= dp[j])
                    dp[i] = max(dp[i], dp[j] + 1);
            ans = max(ans, dp[i]);
        }
        return ans;
    }
};

