        dp = [float('-inf')]
        best = 0
        for i, v in enumerate(nums):
            c = i - v
            lo, hi = 0, len(dp) - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if dp[mid] <= c and mid <= v:
                    lo = mid
                else:
                    hi = mid - 1
            t = lo
            if dp[t] <= c and t <= v:
                if t + 1 == len(dp):
                    dp.append(c)
                else:
                    dp[t + 1] = min(dp[t + 1], c)
                best = max(best, t + 1)
        return best

