class Solution {
    public int maxFixedPoints(int[] nums) {
        List<Integer> dp = new ArrayList<>();
        dp.add(Integer.MIN_VALUE / 2);
        int best = 0;
        for (int i = 0; i < nums.length; ++i) {
            int c = i - nums[i], v = nums[i];
            int lo = 0, hi = dp.size() - 1;
            while (lo < hi) {
                int mid = (lo + hi + 1) / 2;
                if (dp.get(mid) <= c && mid <= v) lo = mid;
                else hi = mid - 1;
            }
            int t = lo;
            if (dp.get(t) <= c && t <= v) {
                if (t + 1 == dp.size()) dp.add(c);
                else dp.set(t + 1, Math.min(dp.get(t + 1), c));
                best = Math.max(best, t + 1);
            }
        }
        return best;
    }
}

